const base = {
  rate: 2,
  get price() {
    return this.rate * 10;
  },
  set price(value) {
    this.rate = value / 10;
  },
};

const sale = { rate: 1 };

console.log(Reflect.get(base, "price"));
console.log(Reflect.get(base, "price", sale));

Reflect.set(base, "price", 50, sale);
console.log(base.rate, sale.rate);
